export default function AboutPage() {
  return (
    <section className="p-10 text-center">
      <h1 className="text-4xl font-bold text-gray-900">About Our Company</h1>
      <p className="mt-4 text-lg text-gray-600 max-w-3xl mx-auto">
        We are a leading packaging solutions provider, delivering eco-friendly
        and customizable packaging for businesses worldwide. Our mission is to
        create sustainable and innovative packaging that stands out.
      </p>
    </section>
  );
}
